# timeouts and bounded failover to the other replica
proxy_connect_timeout 1s;
proxy_send_timeout 5s;
proxy_read_timeout 5s;
proxy_next_upstream error timeout http_502 http_504;   # POSTs are never re-sent (non_idempotent off)
proxy_next_upstream_tries 2;
proxy_next_upstream_timeout 4s;
proxy_http_version 1.1;
proxy_set_header Connection "";
proxy_set_header Host $host;
proxy_set_header X-Request-ID $req_id;
proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;

# replicas with passive health checking (ejected for 5s after 2 failures)
upstream student_svc {
    server student-1:8000 max_fails=2 fail_timeout=5s;
    server student-2:8000 max_fails=2 fail_timeout=5s;
    keepalive 32;
}
upstream payment_svc {
    server payment-1:8000 max_fails=2 fail_timeout=5s;
